const confirmTranslationsHuman = `-- name: ConfirmTranslationsHuman :many
UPDATE translations t
SET step_edited      = t.step_edited OR t.active_text IS DISTINCT FROM i.text,
    qe_note          = CASE WHEN t.active_text IS DISTINCT FROM i.text THEN NULL ELSE t.qe_note END,
    active_text      = i.text,
    active_rich_text = CASE WHEN i.has_rich THEN i.rich_text END,
    status           = 'approved',
    confirmed_via    = 'user',
    edit_distance    = i.edit_distance,
    edited_by        = $1::bigint,
    updated_at       = now()
FROM (
    SELECT unnest($2::bigint[])                AS id,
           unnest($3::text[])                AS text,
           unnest($4::text[])           AS rich_text,
           unnest($5::bool[])             AS has_rich,
           unnest($6::int[])        AS edit_distance,
           unnest($7::timestamptz[]) AS expected_updated_at
) i
WHERE t.id = i.id
  AND t.updated_at = i.expected_updated_at
  AND NOT translation_held_by_other(t.id, $1::bigint)
RETURNING t.id
`

type ConfirmTranslationsHumanParams struct {
	EditedBy          int64                `json:"edited_by"`
	Ids               []int64              `json:"ids"`
	Texts             []string             `json:"texts"`
	RichTexts         []string             `json:"rich_texts"`
	HasRich           []bool               `json:"has_rich"`
	EditDistances     []int32              `json:"edit_distances"`
	ExpectedUpdatedAt []pgtype.Timestamptz `json:"expected_updated_at"`
}

// Internal: the caller resolved @ids from the tenant-scoped job.
// UpdateTranslationHuman for many rows of a bulk confirm (no editing time):
// each row is written only while its updated_at is still the one read and no
// other user holds it; the ids written are returned. has_rich false stores no
// rich text.
func (q *Queries) ConfirmTranslationsHuman(ctx context.Context, arg ConfirmTranslationsHumanParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, confirmTranslationsHuman,
		arg.EditedBy,
		arg.Ids,
		arg.Texts,
		arg.RichTexts,
		arg.HasRich,
		arg.EditDistances,
		arg.ExpectedUpdatedAt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

