const countQAIssuesByJob = `-- name: CountQAIssuesByJob :many
SELECT (CASE WHEN qr.ignored THEN 'ignored' ELSE qr.severity END)::text AS bucket,
       count(*)::int AS count
FROM qa_results qr
JOIN translations t ON t.id = qr.translation_id
JOIN segments s ON s.id = t.segment_id
JOIN files f ON f.id = s.file_id
WHERE f.id = $1 AND t.target_language = $2
GROUP BY 1
`

type CountQAIssuesByJobParams struct {
	FileID         int64  `json:"file_id"`
	TargetLanguage string `json:"target_language"`
}

type CountQAIssuesByJobRow struct {
	Bucket string `json:"bucket"`
	Count  int32  `json:"count"`
}

// Internal: caller must have tenant-verified the job (GetJobTenant).
// Ignored findings leave their severity bucket and land in 'ignored', so the
// summary counts only what still needs attention.
func (q *Queries) CountQAIssuesByJob(ctx context.Context, arg CountQAIssuesByJobParams) ([]CountQAIssuesByJobRow, error) {
	rows, err := q.db.Query(ctx, countQAIssuesByJob, arg.FileID, arg.TargetLanguage)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CountQAIssuesByJobRow{}
	for rows.Next() {
		var i CountQAIssuesByJobRow
		if err := rows.Scan(&i.Bucket, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

