const countTMFRMatches = `-- name: CountTMFRMatches :one
WITH m AS (
  SELECT
    CASE WHEN $3::bool THEN source_text ELSE lower(source_text) END AS src,
    CASE WHEN $3::bool THEN target_text ELSE lower(target_text) END AS tgt,
    CASE WHEN $3::bool THEN $4::text ELSE lower($4::text) END AS f
  FROM translation_memory
  WHERE tm_id = $5
    AND ($6::text = '' OR source_language = $6)
    AND ($7::text = '' OR target_language = $7)
    AND (
      ($1::bool AND CASE WHEN $3::bool THEN source_text LIKE $8::text
                                 ELSE source_text ILIKE $8::text END)
      OR ($2::bool AND CASE WHEN $3::bool THEN target_text LIKE $8::text
                                    ELSE target_text ILIKE $8::text END)
    )
)
SELECT count(*)::bigint AS entries,
       coalesce(sum(
         CASE WHEN $1::bool THEN (length(src) - length(replace(src, f, ''))) / length(f) ELSE 0 END
         + CASE WHEN $2::bool THEN (length(tgt) - length(replace(tgt, f, ''))) / length(f) ELSE 0 END
       ), 0)::bigint AS replacements
FROM m
`

type CountTMFRMatchesParams struct {
	InSource       bool   `json:"in_source"`
	InTarget       bool   `json:"in_target"`
	CaseSensitive  bool   `json:"case_sensitive"`
	Find           string `json:"find"`
	TmID           int64  `json:"tm_id"`
	SourceLanguage string `json:"source_language"`
	TargetLanguage string `json:"target_language"`
	Pattern        string `json:"pattern"`
}

type CountTMFRMatchesRow struct {
	Entries      int64 `json:"entries"`
	Replacements int64 `json:"replacements"`
}

// Totals of FindTMEntriesForFR over the whole TM: matching entries and
// occurrences of @find in the searched fields (case-folded with lower() when
// not @case_sensitive).
func (q *Queries) CountTMFRMatches(ctx context.Context, arg CountTMFRMatchesParams) (CountTMFRMatchesRow, error) {
	row := q.db.QueryRow(ctx, countTMFRMatches,
		arg.InSource,
		arg.InTarget,
		arg.CaseSensitive,
		arg.Find,
		arg.TmID,
		arg.SourceLanguage,
		arg.TargetLanguage,
		arg.Pattern,
	)
	var i CountTMFRMatchesRow
	err := row.Scan(&i.Entries, &i.Replacements)
	return i, err
}

