const ensurePendingAutoAnalysis = `-- name: EnsurePendingAutoAnalysis :one
INSERT INTO analyses (
    tenant_id,
    project_id,
    name,
    source_language,
    job_ids,
    settings_snapshot,
    is_auto
) VALUES (
    $1,
    $2,
    $3,
    $4,
    '{}',
    '{}'::jsonb,
    true
)
ON CONFLICT (project_id) WHERE is_auto AND status = 'pending' AND deleted_at IS NULL
DO NOTHING
RETURNING id, tenant_id, project_id, name, status, error_message, source_language, job_ids, created_by, created_at, completed_at, settings_snapshot, is_auto, deleted_at
`

type EnsurePendingAutoAnalysisParams struct {
	TenantID       int64  `json:"tenant_id"`
	ProjectID      int64  `json:"project_id"`
	Name           string `json:"name"`
	SourceLanguage string `json:"source_language"`
}

// Coalescing insert for auto-analyze-on-upload. Ensures AT MOST ONE
// pending auto analysis per project: the partial unique index
// uq_pending_auto_analysis makes a second file in the same upload (or a burst
// of uploads) hit ON CONFLICT DO NOTHING and return no row. job_ids stays empty
// — the worker resolves the project's job set at run time, so files that join
// the batch late are still covered.
func (q *Queries) EnsurePendingAutoAnalysis(ctx context.Context, arg EnsurePendingAutoAnalysisParams) (Analysis, error) {
	row := q.db.QueryRow(ctx, ensurePendingAutoAnalysis,
		arg.TenantID,
		arg.ProjectID,
		arg.Name,
		arg.SourceLanguage,
	)
	var i Analysis
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.ProjectID,
		&i.Name,
		&i.Status,
		&i.ErrorMessage,
		&i.SourceLanguage,
		&i.JobIds,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.CompletedAt,
		&i.SettingsSnapshot,
		&i.IsAuto,
		&i.DeletedAt,
	)
	return i, err
}

