const findConceptsByTerm = `-- name: FindConceptsByTerm :many
SELECT c.id, c.definition, c.domain
FROM term_concept c
WHERE c.term_base_id = $1
  AND c.deleted_at IS NULL
  AND ($2::bool = false OR c.domain = $3)
  AND EXISTS (
    SELECT 1 FROM term t
    WHERE t.concept_id = c.id AND t.deleted_at IS NULL
      AND t.text = $4
      AND ($5::text = '' OR t.language = $5)
  )
ORDER BY c.id
LIMIT $6
`

type FindConceptsByTermParams struct {
	TermBaseID   int64  `json:"term_base_id"`
	FilterDomain bool   `json:"filter_domain"`
	Domain       string `json:"domain"`
	Text         string `json:"text"`
	Language     string `json:"language"`
	RowLimit     int32  `json:"row_limit"`
}

type FindConceptsByTermRow struct {
	ID         int64  `json:"id"`
	Definition string `json:"definition"`
	Domain     string `json:"domain"`
}

// Concepts in a base that contain a term with EXACT text (case-sensitive, no
// ILIKE), optionally narrowed to an exact language and/or exact domain. Backs the
// MCP find_concepts lookup: a model resolves a concept_id from a known term
// without needing a project the base is assigned to. filter_domain=false ignores
// the domain arg entirely; =true matches c.domain exactly (including ”).
func (q *Queries) FindConceptsByTerm(ctx context.Context, arg FindConceptsByTermParams) ([]FindConceptsByTermRow, error) {
	rows, err := q.db.Query(ctx, findConceptsByTerm,
		arg.TermBaseID,
		arg.FilterDomain,
		arg.Domain,
		arg.Text,
		arg.Language,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FindConceptsByTermRow{}
	for rows.Next() {
		var i FindConceptsByTermRow
		if err := rows.Scan(&i.ID, &i.Definition, &i.Domain); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

