const findTMEntriesForFR = `-- name: FindTMEntriesForFR :many
SELECT id, source_language, target_language, source_text, target_text, created_at, tm_id, source_hash, target_hash, updated_at, created_by, updated_by, tu_id, usage_count, source_rich_text, target_rich_text, prev_source_hash, next_source_hash FROM translation_memory
WHERE tm_id = $1
  AND ($2::text = '' OR source_language = $2)
  AND ($3::text = '' OR target_language = $3)
  AND id > $4::bigint
  AND (
    ($5::bool AND CASE WHEN $6::bool THEN source_text LIKE $7::text
                               ELSE source_text ILIKE $7::text END)
    OR ($8::bool AND CASE WHEN $6::bool THEN target_text LIKE $7::text
                                  ELSE target_text ILIKE $7::text END)
  )
ORDER BY id
LIMIT $9::int
`

type FindTMEntriesForFRParams struct {
	TmID           int64  `json:"tm_id"`
	SourceLanguage string `json:"source_language"`
	TargetLanguage string `json:"target_language"`
	AfterID        int64  `json:"after_id"`
	InSource       bool   `json:"in_source"`
	CaseSensitive  bool   `json:"case_sensitive"`
	Pattern        string `json:"pattern"`
	InTarget       bool   `json:"in_target"`
	PageLimit      int32  `json:"page_limit"`
}

// One page of the entries of ONE TM whose source (@in_source) or target
// (@in_target) contains @pattern, a LIKE pattern ('%term%', wildcards
// escaped), in id order after @after_id. The route has already checked the TM
// belongs to the caller's tenant. Empty language filters match any language.
// LIKE and ILIKE are what idx_tm_source_trgm and idx_tm_target_trgm can serve.
func (q *Queries) FindTMEntriesForFR(ctx context.Context, arg FindTMEntriesForFRParams) ([]TranslationMemory, error) {
	rows, err := q.db.Query(ctx, findTMEntriesForFR,
		arg.TmID,
		arg.SourceLanguage,
		arg.TargetLanguage,
		arg.AfterID,
		arg.InSource,
		arg.CaseSensitive,
		arg.Pattern,
		arg.InTarget,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TranslationMemory{}
	for rows.Next() {
		var i TranslationMemory
		if err := rows.Scan(
			&i.ID,
			&i.SourceLanguage,
			&i.TargetLanguage,
			&i.SourceText,
			&i.TargetText,
			&i.CreatedAt,
			&i.TmID,
			&i.SourceHash,
			&i.TargetHash,
			&i.UpdatedAt,
			&i.CreatedBy,
			&i.UpdatedBy,
			&i.TuID,
			&i.UsageCount,
			&i.SourceRichText,
			&i.TargetRichText,
			&i.PrevSourceHash,
			&i.NextSourceHash,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

