const fuzzyLookupTM = `-- name: FuzzyLookupTM :many
SELECT id, tm_id, source_language, target_language, source_text, target_text,
       source_rich_text, target_rich_text, created_at, prev_source_hash, next_source_hash,
       similarity(source_text, $1::text) AS score
FROM translation_memory
WHERE tm_id = $2
  AND SPLIT_PART(source_language, '-', 1) = SPLIT_PART($3::text, '-', 1)
  AND SPLIT_PART(target_language, '-', 1) = SPLIT_PART($4::text, '-', 1)
  AND source_text % $1::text
  AND similarity(source_text, $1::text) >= $5::real
ORDER BY score DESC
LIMIT $6::int
`

type FuzzyLookupTMParams struct {
	Query          string  `json:"query"`
	TmID           int64   `json:"tm_id"`
	SourceLanguage string  `json:"source_language"`
	TargetLanguage string  `json:"target_language"`
	Threshold      float32 `json:"threshold"`
	EntryLimit     int32   `json:"entry_limit"`
}

type FuzzyLookupTMRow struct {
	ID             int64              `json:"id"`
	TmID           int64              `json:"tm_id"`
	SourceLanguage string             `json:"source_language"`
	TargetLanguage string             `json:"target_language"`
	SourceText     string             `json:"source_text"`
	TargetText     string             `json:"target_text"`
	SourceRichText *string            `json:"source_rich_text"`
	TargetRichText *string            `json:"target_rich_text"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
	PrevSourceHash *string            `json:"prev_source_hash"`
	NextSourceHash *string            `json:"next_source_hash"`
	Score          float32            `json:"score"`
}

// Stage 1 of the find/score split: @threshold MUST stay low for
// recall — the application Scorer rescores and applies the display threshold
// after. Bumping @threshold drops short-sentence fuzzy candidates (Bug 2).
//
// Sublanguage-aware on both sides (see LookupTM). Callers rescore with
// translationmemory.PenalizeSublanguage before comparing against the display
// threshold, so a variant candidate has to clear a slightly higher bar.
// prev/next_source_hash let an exact hit score 101% in context.
//
// `%` is what lets idx_tm_source_trgm serve the search; it compares against
// pg_trgm.similarity_threshold, so run it through
// translationmemory.FuzzyLookup, which sets that to @threshold first. The
// similarity() test keeps the result exact whatever the setting.
func (q *Queries) FuzzyLookupTM(ctx context.Context, arg FuzzyLookupTMParams) ([]FuzzyLookupTMRow, error) {
	rows, err := q.db.Query(ctx, fuzzyLookupTM,
		arg.Query,
		arg.TmID,
		arg.SourceLanguage,
		arg.TargetLanguage,
		arg.Threshold,
		arg.EntryLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FuzzyLookupTMRow{}
	for rows.Next() {
		var i FuzzyLookupTMRow
		if err := rows.Scan(
			&i.ID,
			&i.TmID,
			&i.SourceLanguage,
			&i.TargetLanguage,
			&i.SourceText,
			&i.TargetText,
			&i.SourceRichText,
			&i.TargetRichText,
			&i.CreatedAt,
			&i.PrevSourceHash,
			&i.NextSourceHash,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

