const getJobTranslationCounts = `-- name: GetJobTranslationCounts :one
SELECT
    COALESCE(SUM(st.segments), 0)::int AS total,
    COALESCE(SUM(st.segments) FILTER (WHERE st.text_state = 0), 0)::int AS untranslated,
    COALESCE(SUM(st.segments) FILTER (WHERE st.status = 'needs_review' AND st.text_state > 0
        AND NOT st.step_edited AND NOT st.predict_this_round), 0)::int AS pre_translated,
    COALESCE(SUM(st.segments) FILTER (WHERE st.status = 'needs_review' AND st.text_state > 0
        AND (st.step_edited OR st.predict_this_round)), 0)::int AS needs_review,
    COALESCE(SUM(st.segments) FILTER (WHERE st.status = 'auto_approved'), 0)::int AS auto_approved,
    COALESCE(SUM(st.segments) FILTER (WHERE st.status = 'approved'), 0)::int AS approved,
    COALESCE(SUM(st.segments) FILTER (WHERE NOT st.locked AND st.text_state > 0
        AND st.status NOT IN ('approved', 'auto_approved')), 0)::int AS clearable_non_confirmed,
    COALESCE(SUM(st.segments) FILTER (WHERE NOT st.locked AND st.text_state > 0), 0)::int AS clearable_all
FROM job_translation_stats st
WHERE st.file_id = $1 AND st.target_language = $2
`

type GetJobTranslationCountsParams struct {
	FileID         int64  `json:"file_id"`
	TargetLanguage string `json:"target_language"`
}

type GetJobTranslationCountsRow struct {
	Total                 int32 `json:"total"`
	Untranslated          int32 `json:"untranslated"`
	PreTranslated         int32 `json:"pre_translated"`
	NeedsReview           int32 `json:"needs_review"`
	AutoApproved          int32 `json:"auto_approved"`
	Approved              int32 `json:"approved"`
	ClearableNonConfirmed int32 `json:"clearable_non_confirmed"`
	ClearableAll          int32 `json:"clearable_all"`
}

// Counts from job_translation_stats, which the database keeps up to date on
// every translation write. The status enum is needs_review/auto_approved/approved;
// untranslated + pre_translated are derived sub-states of needs_review that
// the analysis bar + pipeline-action gating rely on. Partition is exhaustive: untranslated, pre_translated,
// needs_review(display), auto_approved, approved sum to total.
//
//	untranslated   = no target text (text_state 0)
//	pre_translated = needs_review with text nobody edited in the current step
//	                 and no AI verdict from the current step round
//	needs_review   = needs_review with text edited in the current step, or
//	                 given an AI verdict in its current round
//
// The clear counts exclude locked and already-empty rows and mirror the
// ClearTranslationsByJob predicate, so the Clear-translations dialog shows
// the real number.
func (q *Queries) GetJobTranslationCounts(ctx context.Context, arg GetJobTranslationCountsParams) (GetJobTranslationCountsRow, error) {
	row := q.db.QueryRow(ctx, getJobTranslationCounts, arg.FileID, arg.TargetLanguage)
	var i GetJobTranslationCountsRow
	err := row.Scan(
		&i.Total,
		&i.Untranslated,
		&i.PreTranslated,
		&i.NeedsReview,
		&i.AutoApproved,
		&i.Approved,
		&i.ClearableNonConfirmed,
		&i.ClearableAll,
	)
	return i, err
}

const getJobsApproachingDeadline = `-- name: GetJobsApproachingDeadline :many

SELECT j.id AS job_id,
       jsa.deadline AS deadline,
       j.file_id, j.target_language,
       f.name AS file_name, p.id AS project_id, p.name AS project_name,
       p.tenant_id AS tenant_id,
       jsa.assigned_to, ws.name AS step_name
FROM jobs j
JOIN job_step_assignments jsa ON jsa.id = j.current_step_id
JOIN workflow_steps ws ON ws.id = jsa.workflow_step_id
JOIN files f ON f.id = j.file_id
JOIN projects p ON p.id = f.project_id
JOIN tenants t ON t.id = p.tenant_id
WHERE jsa.deadline IS NOT NULL
  AND t.kind <> 'demo'
  AND ($1::bigint IS NULL OR p.tenant_id = $1)
  AND p.deleted_at IS NULL
  AND jsa.deadline BETWEEN now() AND now() + interval '24 hours'
  AND NOT EXISTS (
    SELECT 1 FROM notifications n
    WHERE n.reference_id = j.id
      AND n.reference_type = 'job'
      AND n.event_type = 'deadline'
      AND n.created_at > now() - interval '20 hours'
  )
`

type GetJobsApproachingDeadlineRow struct {
	JobID          int64              `json:"job_id"`
	Deadline       pgtype.Timestamptz `json:"deadline"`
	FileID         int64              `json:"file_id"`
	TargetLanguage string             `json:"target_language"`
	FileName       string             `json:"file_name"`
	ProjectID      int64              `json:"project_id"`
	ProjectName    string             `json:"project_name"`
	TenantID       int64              `json:"tenant_id"`
	AssignedTo     *int64             `json:"assigned_to"`
	StepName       string             `json:"step_name"`
}

// ============================================================
// Deadline queries
// ============================================================
// Internal: the hourly cron passes a NULL tenant_id and scans every org; the
// manual trigger, an org owner/admin route, passes the caller's tenant_id.
// tenant_id flows out through the projects JOIN so the handler tags
// downstream notifications without a follow-up GetProjectByID round-trip.
//
// Deadline semantics: the deadline lives on the ACTIVE step
// assignment (jobs.current_step_id → job_step_assignments.deadline), and this
// query reads that column and nothing else — a project's own date is never
// substituted here. It can still be the value stored there: materialization
// seeds an unscheduled step's assignment from the project deadline,
// so such a task reminds like any other. The reminder
// goes to the active step's assignee.
//
// Uses idx_jsa_deadline (migration 046). Dedup is still keyed on the JOB id
// (reference_type='job'), so the existing idx_notifications_deadline_dedup
// (migration 027) and the downstream notification shape are unchanged.
//
// The demo organization (tenants.kind = 'demo') is skipped:
// its assignees are synthetic users who get no email.
func (q *Queries) GetJobsApproachingDeadline(ctx context.Context, tenantID *int64) ([]GetJobsApproachingDeadlineRow, error) {
	rows, err := q.db.Query(ctx, getJobsApproachingDeadline, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetJobsApproachingDeadlineRow{}
	for rows.Next() {
		var i GetJobsApproachingDeadlineRow
		if err := rows.Scan(
			&i.JobID,
			&i.Deadline,
			&i.FileID,
			&i.TargetLanguage,
			&i.FileName,
			&i.ProjectID,
			&i.ProjectName,
			&i.TenantID,
			&i.AssignedTo,
			&i.StepName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

