const getPendingInvitesByEmail = `-- name: GetPendingInvitesByEmail :many
SELECT id, tenant_id, email, role, invited_by, token, accepted_at, expires_at, created_at FROM invites WHERE email = $1 AND accepted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM tenants t WHERE t.id = invites.tenant_id AND t.status = 'deleting')
ORDER BY created_at DESC
`

// Sign-in auto-match: any pending (un-accepted), non-revoked invite for this
// email, across tenants. Deliberately NOT filtered by expires_at — a verified
// identity plus an admin-created invite is authorization enough, so someone
// added via the Vendors list can still sign in after the invite link would
// have "expired". Expiry only guards the emailed token link
// (GetPendingUnexpiredInviteByToken). Row present = allowed;
// revoked (DeleteInvite) = gone.
// An organization being deleted honours no invite.
func (q *Queries) GetPendingInvitesByEmail(ctx context.Context, email string) ([]Invite, error) {
	rows, err := q.db.Query(ctx, getPendingInvitesByEmail, email)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Invite{}
	for rows.Next() {
		var i Invite
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Email,
			&i.Role,
			&i.InvitedBy,
			&i.Token,
			&i.AcceptedAt,
			&i.ExpiresAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

