const importBilingualTargets = `-- name: ImportBilingualTargets :execrows
WITH input AS (
    SELECT unnest($2::bigint[]) AS segment_id,
           unnest($3::text[])        AS text,
           unnest($4::text[])   AS rich_text
), stamped AS (
    UPDATE translations t
    SET active_text      = i.text,
        active_rich_text = NULLIF(i.rich_text, ''),
        status           = 'needs_review',
        origin           = 'file_import',
        tm_match_percent = NULL,
        updated_at       = now()
    FROM input i
    WHERE t.segment_id = i.segment_id AND t.target_language = $5
    RETURNING t.id, i.text, NULLIF(i.rich_text, '') AS rich_text
)
INSERT INTO translation_history (translation_id, kind, text, rich_text, created_by, details)
SELECT stamped.id, 'file_import', stamped.text, stamped.rich_text, $1::bigint, '{}'::jsonb
FROM stamped
`

type ImportBilingualTargetsParams struct {
	CreatedBy      int64    `json:"created_by"`
	SegmentIds     []int64  `json:"segment_ids"`
	Texts          []string `json:"texts"`
	RichTexts      []string `json:"rich_texts"`
	TargetLanguage string   `json:"target_language"`
}

// XLSX bilingual import, one target language in one statement: stamps each
// (segment, @target_language) translation with the imported text as
// pre-translated (not approved — translators still review), sets origin
// file_import, and records the file_import history row. An empty rich text
// means the cell has no inline tags. Internal: @segment_ids are the segments
// the upload just created, in its transaction.
func (q *Queries) ImportBilingualTargets(ctx context.Context, arg ImportBilingualTargetsParams) (int64, error) {
	result, err := q.db.Exec(ctx, importBilingualTargets,
		arg.CreatedBy,
		arg.SegmentIds,
		arg.Texts,
		arg.RichTexts,
		arg.TargetLanguage,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

