const listActiveStepsForProject = `-- name: ListActiveStepsForProject :many
SELECT DISTINCT ON (jsa.job_id)
       jsa.id AS step_assignment_id, jsa.job_id, ws.name AS step_name, ws.step_type,
       ws.step_order AS step_order, jsa.status, jsa.deadline,
       jsa.assigned_to, u.name AS assignee_name,
       (ws.ai_router_id IS NOT NULL)::bool AS is_ai_step,
       (SELECT COUNT(*) FROM workflow_steps ws2
        WHERE ws2.settings_profile_id = ws.settings_profile_id
          AND ws2.step_order > ws.step_order) = 0 AS is_last_step
FROM job_step_assignments jsa
JOIN workflow_steps ws ON ws.id = jsa.workflow_step_id
JOIN jobs j ON j.id = jsa.job_id
JOIN files f ON f.id = j.file_id
LEFT JOIN users u ON u.id = jsa.assigned_to
WHERE f.project_id = $1
  -- job_ids NULL returns every job; otherwise only those jobs.
  AND ($2::bigint[] IS NULL OR jsa.job_id = ANY($2::bigint[]))
ORDER BY jsa.job_id, (jsa.status = 'in_progress') DESC, (jsa.status = 'completed') DESC, ws.step_order DESC
`

type ListActiveStepsForProjectParams struct {
	ProjectID int64   `json:"project_id"`
	JobIds    []int64 `json:"job_ids"`
}

type ListActiveStepsForProjectRow struct {
	StepAssignmentID int64              `json:"step_assignment_id"`
	JobID            int64              `json:"job_id"`
	StepName         string             `json:"step_name"`
	StepType         string             `json:"step_type"`
	StepOrder        int32              `json:"step_order"`
	Status           string             `json:"status"`
	Deadline         pgtype.Timestamptz `json:"deadline"`
	AssignedTo       *int64             `json:"assigned_to"`
	AssigneeName     *string            `json:"assignee_name"`
	IsAiStep         bool               `json:"is_ai_step"`
	IsLastStep       bool               `json:"is_last_step"`
}

// One representative workflow-step row per job in a project (batched, avoids
// N+1): the job's current task. DISTINCT ON picks the in_progress step when
// there is one, otherwise the last completed step, otherwise the latest step —
// the same rule as taskedit's edit guard and the editor's currentTask, so the
// matrix cell, Open and the job row agree. Completed-workflow jobs
// (current_step_id NULL) still surface a step assignment to carry/edit a
// deadline. `step_order` backs first-step-only gating (Apply TM/MT);
// `step_assignment_id` + `deadline` back the inline deadline editor; `is_ai_step`
// gates the manager QE+APE re-run button.
func (q *Queries) ListActiveStepsForProject(ctx context.Context, arg ListActiveStepsForProjectParams) ([]ListActiveStepsForProjectRow, error) {
	rows, err := q.db.Query(ctx, listActiveStepsForProject, arg.ProjectID, arg.JobIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListActiveStepsForProjectRow{}
	for rows.Next() {
		var i ListActiveStepsForProjectRow
		if err := rows.Scan(
			&i.StepAssignmentID,
			&i.JobID,
			&i.StepName,
			&i.StepType,
			&i.StepOrder,
			&i.Status,
			&i.Deadline,
			&i.AssignedTo,
			&i.AssigneeName,
			&i.IsAiStep,
			&i.IsLastStep,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listAllForBilingualExport = `-- name: ListAllForBilingualExport :many
SELECT s.id AS segment_id, s.segment_key, s.source_text, s.source_rich_text, s.position,
       t.active_text, t.active_rich_text,
       t.status, t.locked, t.origin, t.tm_match_percent,
       mtu.source_text AS match_source_text, mtu.target_text AS match_target_text
FROM segments s
LEFT JOIN translations t ON t.segment_id = s.id AND t.target_language = $1
LEFT JOIN LATERAL (
    SELECT h.tm_entry_id
    FROM translation_history h
    WHERE t.origin = 'tm'
      AND h.translation_id = t.id
      AND h.kind = 'tm'
    ORDER BY h.created_at DESC, h.id DESC
    LIMIT 1
) m ON true
LEFT JOIN translation_memory mtu ON mtu.id = m.tm_entry_id
    AND EXISTS (SELECT 1 FROM tm_collections c
                WHERE c.id = mtu.tm_id AND c.tenant_id = $2 AND c.deleted_at IS NULL)
WHERE s.file_id = $3
ORDER BY s.position
`

