const listJobSegmentsPage = `-- name: ListJobSegmentsPage :many
SELECT
    t.id             AS translation_id,
    s.id             AS segment_id,
    s.position       AS position,
    s.source_text    AS source_text,
    t.active_text    AS target_text,
    t.status         AS status,
    t.origin         AS origin,
    t.tm_match_percent AS tm_match_percent,
    t.updated_at     AS updated_at
FROM segments s
JOIN files f ON f.id = s.file_id
JOIN projects p ON p.id = f.project_id
JOIN translations t ON t.segment_id = s.id AND t.target_language = $1::text
WHERE s.file_id = $2::bigint
  AND p.tenant_id = $3::bigint AND p.deleted_at IS NULL
  AND ($4::text = '' OR t.status::text = $4::text)
  AND ($5::text = '' OR t.origin::text = $5::text)
  AND ($6::text = ''
       OR s.source_text ILIKE '%' || $6::text || '%'
       OR coalesce(t.active_text, '') ILIKE '%' || $6::text || '%')
  AND s.position >= $7::int
ORDER BY s.position
LIMIT $8::int
`

type ListJobSegmentsPageParams struct {
	TargetLanguage string `json:"target_language"`
	FileID         int64  `json:"file_id"`
	TenantID       int64  `json:"tenant_id"`
	Status         string `json:"status"`
	Origin         string `json:"origin"`
	Query          string `json:"query"`
	Cursor         int32  `json:"cursor"`
	RowLimit       int32  `json:"row_limit"`
}

type ListJobSegmentsPageRow struct {
	TranslationID  int64                 `json:"translation_id"`
	SegmentID      int64                 `json:"segment_id"`
	Position       int32                 `json:"position"`
	SourceText     string                `json:"source_text"`
	TargetText     *string               `json:"target_text"`
	Status         TranslationStatus     `json:"status"`
	Origin         NullTranslationOrigin `json:"origin"`
	TmMatchPercent *int16                `json:"tm_match_percent"`
	UpdatedAt      pgtype.Timestamptz    `json:"updated_at"`
}

// Source + target for one job, filtered and cursor-paginated.
//
// Serves the MCP segment tool and the customer API's segment list; the CAT
// editor loads segments and translations separately. Tenant scoping is
// structural via files→projects.
//
// Empty-string filters mean "no filter"; enums are compared as ::text so an
// unknown value simply matches nothing instead of erroring on a bad enum cast.
//
// The cursor is a segment position and the comparison is INCLUSIVE (>=), i.e.
// "start at this position". That's load-bearing: segment positions are 0-based,
// and an omitted cursor arrives as 0, so an exclusive `>` would silently skip
// the very first segment of every file. Callers advance by passing
// last_position + 1, which the backend returns as next_cursor.
func (q *Queries) ListJobSegmentsPage(ctx context.Context, arg ListJobSegmentsPageParams) ([]ListJobSegmentsPageRow, error) {
	rows, err := q.db.Query(ctx, listJobSegmentsPage,
		arg.TargetLanguage,
		arg.FileID,
		arg.TenantID,
		arg.Status,
		arg.Origin,
		arg.Query,
		arg.Cursor,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListJobSegmentsPageRow{}
	for rows.Next() {
		var i ListJobSegmentsPageRow
		if err := rows.Scan(
			&i.TranslationID,
			&i.SegmentID,
			&i.Position,
			&i.SourceText,
			&i.TargetText,
			&i.Status,
			&i.Origin,
			&i.TmMatchPercent,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

