const listOtherTargetsForSource = `-- name: ListOtherTargetsForSource :many

SELECT COALESCE(t2.active_text, '') AS target_text
FROM translations t2
JOIN segments s2 ON s2.id = t2.segment_id
JOIN files f2 ON f2.id = s2.file_id
WHERE f2.id = $1
  AND t2.target_language = $2
  AND md5(s2.source_text) = md5($3::text)
  AND s2.source_text = $3
  AND t2.id != $4
ORDER BY t2.id
LIMIT 10
`

type ListOtherTargetsForSourceParams struct {
	FileID               int64  `json:"file_id"`
	TargetLanguage       string `json:"target_language"`
	SourceText           string `json:"source_text"`
	ExcludeTranslationID int64  `json:"exclude_translation_id"`
}

// ============================================================
// Segments + translations for QA batch processing
// (loads all translations for a job to run QA checks)
// ============================================================
// For consistency check: find other translations of the same source text in this job.
// ORDER BY is load-bearing: CheckConsistency quotes the first differing row, and
// a finding's message is its identity for the per-finding ignore.
func (q *Queries) ListOtherTargetsForSource(ctx context.Context, arg ListOtherTargetsForSourceParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listOtherTargetsForSource,
		arg.FileID,
		arg.TargetLanguage,
		arg.SourceText,
		arg.ExcludeTranslationID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var target_text string
		if err := rows.Scan(&target_text); err != nil {
			return nil, err
		}
		items = append(items, target_text)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPreTranslatedByFile = `-- name: ListPreTranslatedByFile :many
SELECT t.id, t.segment_id, t.target_language, s.source_text, s.source_rich_text,
       t.active_text, t.active_rich_text, s.position, t.origin
FROM translations t
JOIN segments s ON s.id = t.segment_id
WHERE s.file_id = $1
  AND t.target_language = $2
  AND t.active_text IS NOT NULL
  AND t.status = 'needs_review'
  AND t.predict_outcome IS NULL
  AND (
    (t.origin IS NOT NULL AND t.edited_by IS NULL)
    OR ($3::bool AND NOT t.locked AND coalesce(t.active_text, '') <> '')
  )
ORDER BY s.position
`

type ListPreTranslatedByFileParams struct {
	FileID         int64  `json:"file_id"`
	TargetLanguage string `json:"target_language"`
	ReviewAll      bool   `json:"review_all"`
}

type ListPreTranslatedByFileRow struct {
	ID             int64                 `json:"id"`
	SegmentID      int64                 `json:"segment_id"`
	TargetLanguage string                `json:"target_language"`
	SourceText     string                `json:"source_text"`
	SourceRichText *string               `json:"source_rich_text"`
	ActiveText     *string               `json:"active_text"`
	ActiveRichText *string               `json:"active_rich_text"`
	Position       int32                 `json:"position"`
	Origin         NullTranslationOrigin `json:"origin"`
}

// Rows of one target language the Predict phase should score: MT/TM-filled,
// with text, not yet predicted, not human-edited. Returns active_text.
// 'pre_translated' is the derived state
// `status='needs_review' AND origin IS NOT NULL AND edited_by IS NULL AND
// predict_outcome IS NULL` — automation filled the text, predict hasn't run,
// no human touched it.
// source_rich_text + active_rich_text ride along so QE/APE can show the model
// the inline tags, and so the outcomes that leave the target alone can write
// the row's existing rich text back unchanged.
// position is the segment's place in the file. It is what the batch envelope
// uses to identify a segment to the model, so the number
// the model reads is the one the editor shows.
// @review_all (a step round that re-runs its AI after a rollback) takes every
// unconfirmed, unlocked segment with text, people's text included.
func (q *Queries) ListPreTranslatedByFile(ctx context.Context, arg ListPreTranslatedByFileParams) ([]ListPreTranslatedByFileRow, error) {
	rows, err := q.db.Query(ctx, listPreTranslatedByFile, arg.FileID, arg.TargetLanguage, arg.ReviewAll)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPreTranslatedByFileRow{}
	for rows.Next() {
		var i ListPreTranslatedByFileRow
		if err := rows.Scan(
			&i.ID,
			&i.SegmentID,
			&i.TargetLanguage,
			&i.SourceText,
			&i.SourceRichText,
			&i.ActiveText,
			&i.ActiveRichText,
			&i.Position,
			&i.Origin,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

