const listProjectsFiltered = `-- name: ListProjectsFiltered :many
SELECT p.id, p.name, p.description, p.source_language, p.target_languages, p.created_at, p.updated_at, p.template_id, p.tenant_id, p.deadline, p.settings_profile_id, p.status, p.created_by, p.customer_id, p.client, p.domain, p.deleted_at,
  COALESCE(NULLIF(u.name, ''), u.email, '')::text AS created_by_name,
  COALESCE(cv.value, '')::text AS customer_name,
  cv.id AS customer_value_id
FROM projects p
LEFT JOIN users u ON u.id = p.created_by
LEFT JOIN label_definitions cd ON cd.tenant_id = p.tenant_id
                              AND cd.system_key = 'customer' AND cd.deleted_at IS NULL
LEFT JOIN project_labels cpl ON cpl.project_id = p.id AND cpl.label_definition_id = cd.id
LEFT JOIN label_values cv ON cv.id = cpl.label_value_id AND cv.deleted_at IS NULL
WHERE p.tenant_id = $1 AND p.deleted_at IS NULL
  AND ($2::bigint = 0 OR p.id < $2)
  AND ($3::project_status IS NULL OR p.status = $3::project_status)
  -- customer_id filters by the Customer label's value id.
  AND ($4::bigint IS NULL OR cpl.label_value_id = $4::bigint)
  AND ($5::text IS NULL OR p.source_language = $5::text)
  AND ($6::text IS NULL OR p.target_languages @> ARRAY[$6::text])
  AND ($7::bigint IS NULL OR p.created_by = $7::bigint)
  AND ($8::text IS NULL OR p.name ILIKE '%' || $8::text || '%')
ORDER BY p.id DESC
LIMIT $9
`

type ListProjectsFilteredParams struct {
	TenantID   int64             `json:"tenant_id"`
	Cursor     int64             `json:"cursor"`
	Status     NullProjectStatus `json:"status"`
	CustomerID *int64            `json:"customer_id"`
	SourceLang *string           `json:"source_lang"`
	TargetLang *string           `json:"target_lang"`
	CreatedBy  *int64            `json:"created_by"`
	Q          *string           `json:"q"`
	Lim        int32             `json:"lim"`
}

type ListProjectsFilteredRow struct {
	ID                int64              `json:"id"`
	Name              string             `json:"name"`
	Description       string             `json:"description"`
	SourceLanguage    string             `json:"source_language"`
	TargetLanguages   []string           `json:"target_languages"`
	CreatedAt         pgtype.Timestamptz `json:"created_at"`
	UpdatedAt         pgtype.Timestamptz `json:"updated_at"`
	TemplateID        *int64             `json:"template_id"`
	TenantID          int64              `json:"tenant_id"`
	Deadline          pgtype.Timestamptz `json:"deadline"`
	SettingsProfileID int64              `json:"settings_profile_id"`
	Status            ProjectStatus      `json:"status"`
	CreatedBy         *int64             `json:"created_by"`
	CustomerID        *int64             `json:"customer_id"`
	Client            *string            `json:"client"`
	Domain            *string            `json:"domain"`
	DeletedAt         pgtype.Timestamptz `json:"deleted_at"`
	CreatedByName     string             `json:"created_by_name"`
	CustomerName      string             `json:"customer_name"`
	CustomerValueID   *int64             `json:"customer_value_id"`
}

// Paginated + filtered project list for the UI.
// All filters are optional (NULL → no filter); tenant_id is always applied.
// Sort by id DESC for stable cursor pagination (newest-created first).
// Caller passes limit+1 to detect has_more in the handler.
// created_by_name is the creator's display name, resolved here so a list row
// arrives ready to render (same denormalize-a-name-into-the-payload
// pattern as customer_name in ListTMCollections). Precedence:
//  1. users.name
//  2. users.email  — when the name is blank (the column defaults to an empty
//     string and signup/SSO paths don't always set one)
//  3. blank        — when there is no user at all: created_by is NULL (row
//     predates attribution) or the user was deleted
//
// Customer is a built-in label, so the row's customer is
// the value it picked. Denormalized here for the same reason created_by_name
// is: a list row should arrive ready to render.
func (q *Queries) ListProjectsFiltered(ctx context.Context, arg ListProjectsFilteredParams) ([]ListProjectsFilteredRow, error) {
	rows, err := q.db.Query(ctx, listProjectsFiltered,
		arg.TenantID,
		arg.Cursor,
		arg.Status,
		arg.CustomerID,
		arg.SourceLang,
		arg.TargetLang,
		arg.CreatedBy,
		arg.Q,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListProjectsFilteredRow{}
	for rows.Next() {
		var i ListProjectsFilteredRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Description,
			&i.SourceLanguage,
			&i.TargetLanguages,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TemplateID,
			&i.TenantID,
			&i.Deadline,
			&i.SettingsProfileID,
			&i.Status,
			&i.CreatedBy,
			&i.CustomerID,
			&i.Client,
			&i.Domain,
			&i.DeletedAt,
			&i.CreatedByName,
			&i.CustomerName,
			&i.CustomerValueID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listQAErrorHotspots = `-- name: ListQAErrorHotspots :many
SELECT
    j.id              AS job_id,
    p.id              AS project_id,
    p.name            AS project_name,
    f.name            AS file_name,
    j.target_language AS target_language,
    count(*)::bigint  AS error_count
FROM qa_results qr
JOIN translations t ON t.id = qr.translation_id
JOIN segments s ON s.id = t.segment_id
JOIN files f ON f.id = s.file_id
JOIN projects p ON p.id = f.project_id
JOIN jobs j ON j.file_id = f.id AND j.target_language = t.target_language
WHERE p.tenant_id = $1 AND p.deleted_at IS NULL
  AND p.status = 'in_progress'
  AND j.status <> 'completed'
  AND qr.severity = 'error'
  AND NOT qr.ignored
GROUP BY j.id, p.id, p.name, f.name, j.target_language
ORDER BY error_count DESC, j.id
LIMIT $2
`

