const listSettingsTermsForQA = `-- name: ListSettingsTermsForQA :many
SELECT tgt.id, c.id AS concept_id,
       src.text AS source_term, tgt.text AS target_term,
       tgt.status, src.status AS source_status, c.domain
FROM term src
JOIN term_concept c ON c.id = src.concept_id AND c.deleted_at IS NULL AND src.deleted_at IS NULL
JOIN term tgt ON tgt.concept_id = c.id
  AND tgt.deleted_at IS NULL
JOIN term_bases tb ON tb.id = c.term_base_id AND tb.deleted_at IS NULL
JOIN LATERAL (
  SELECT a.priority
  FROM settings_terminology_assignments a
  WHERE a.term_base_id = tb.id
    AND a.settings_profile_id = $1
    AND (a.source_language = $2
         OR SPLIT_PART(a.source_language, '-', 1) = SPLIT_PART($2, '-', 1))
    AND (a.target_language = $3
         OR SPLIT_PART(a.target_language, '-', 1) = SPLIT_PART($3, '-', 1))
  ORDER BY a.priority ASC
  LIMIT 1
) sta ON true
WHERE (src.language = $2
       OR SPLIT_PART(src.language, '-', 1) = SPLIT_PART($2, '-', 1))
  AND (tgt.language = $3
       OR SPLIT_PART(tgt.language, '-', 1) = SPLIT_PART($3, '-', 1))
ORDER BY
  (CASE WHEN $4::text <> '' AND c.domain ILIKE '%' || $4 || '%' THEN 0 ELSE 1 END) ASC,
  sta.priority ASC, length(src.text) DESC, src.id ASC, tgt.id ASC
`

