const listTMTargetableByFile = `-- name: ListTMTargetableByFile :many
SELECT t.id, t.segment_id, t.target_language, s.source_text, s.source_rich_text,
       translation_held_by_other(t.id, $1::bigint) AS held_by_other
FROM translations t
JOIN segments s ON s.id = t.segment_id
WHERE s.file_id = $2
  AND t.target_language = $3
  AND t.status = 'needs_review'
  AND t.predict_outcome IS NULL
  AND t.edited_by IS NULL
  AND t.locked = false
  AND ($4::bigint[] IS NULL OR t.id = ANY($4::bigint[]))
ORDER BY s.position
`

type ListTMTargetableByFileParams struct {
	ActorID        *int64  `json:"actor_id"`
	FileID         int64   `json:"file_id"`
	TargetLanguage string  `json:"target_language"`
	Ids            []int64 `json:"ids"`
}

type ListTMTargetableByFileRow struct {
	ID             int64   `json:"id"`
	SegmentID      int64   `json:"segment_id"`
	TargetLanguage string  `json:"target_language"`
	SourceText     string  `json:"source_text"`
	SourceRichText *string `json:"source_rich_text"`
	HeldByOther    bool    `json:"held_by_other"`
}

// Segments eligible for the Apply-TM phase (TM overrides unconfirmed MT). Returns
// unconfirmed rows that no human has touched and that predict has not yet
// finalized: edited or confirmed segments are protected.
//
// The eligible rows are `status='needs_review' AND predict_outcome IS NULL`
// (predict has not produced an outcome) AND `edited_by IS NULL` (no human
// edit):
//   - auto_approved / approved — confirmed; excluded by status.
//   - predict-rejected needs_review — predict_outcome IS NOT NULL; excluded.
//   - human-edited needs_review — edited_by IS NOT NULL; excluded.
//   - locked — never pre-translated; excluded.
//
// @ids narrows it to a selection; NULL = every row. held_by_other as in
// ListUntranslatedByFile.
func (q *Queries) ListTMTargetableByFile(ctx context.Context, arg ListTMTargetableByFileParams) ([]ListTMTargetableByFileRow, error) {
	rows, err := q.db.Query(ctx, listTMTargetableByFile,
		arg.ActorID,
		arg.FileID,
		arg.TargetLanguage,
		arg.Ids,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTMTargetableByFileRow{}
	for rows.Next() {
		var i ListTMTargetableByFileRow
		if err := rows.Scan(
			&i.ID,
			&i.SegmentID,
			&i.TargetLanguage,
			&i.SourceText,
			&i.SourceRichText,
			&i.HeldByOther,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTargetsForSources = `-- name: ListTargetsForSources :many
SELECT ranked.source_text, ranked.translation_id, ranked.target_text
FROM (
    SELECT s2.source_text, t2.id AS translation_id,
           COALESCE(t2.active_text, '') AS target_text,
           row_number() OVER (PARTITION BY s2.source_text ORDER BY t2.id) AS rn
    FROM segments s2
    JOIN translations t2 ON t2.segment_id = s2.id AND t2.target_language = $1
    WHERE s2.file_id = $2
      AND md5(s2.source_text) = ANY($3::text[])
      AND s2.source_text = ANY($4::text[])
) ranked
WHERE ranked.rn <= 11
ORDER BY ranked.source_text, ranked.translation_id
`

