const lookupTM = `-- name: LookupTM :one
SELECT id, source_language, target_language, source_text, target_text, created_at, tm_id, source_hash, target_hash, updated_at, created_by, updated_by, tu_id, usage_count, source_rich_text, target_rich_text, prev_source_hash, next_source_hash FROM translation_memory
WHERE tm_id = $1
  AND SPLIT_PART(source_language, '-', 1) = SPLIT_PART($2::text, '-', 1)
  AND source_text = $3
  AND SPLIT_PART(target_language, '-', 1) = SPLIT_PART($4::text, '-', 1)
ORDER BY (target_language = $4) DESC, (source_language = $2) DESC
LIMIT 1
`

type LookupTMParams struct {
	TmID           int64  `json:"tm_id"`
	SourceLanguage string `json:"source_language"`
	SourceText     string `json:"source_text"`
	TargetLanguage string `json:"target_language"`
}

// Sublanguage-aware on BOTH sides: es-mx matches es-mx entries AND es entries,
// and an es entry is reachable from an es-mx project. Exact locale wins via the
// ORDER BY; callers charge translationmemory.SublanguagePenalty when they land
// on a variant, so a variant never reads as a true exact match.
//
// Plain equality on SPLIT_PART rather than `col = $n OR SPLIT_PART(...)`: the
// OR form can't use a btree index, and idx_tm_exact_match_base exists purely to
// keep this lookup off a sequential scan (see migration 017 — unindexed exact
// lookups took 6+ minutes on 12K segments). The OR was also redundant, since an
// exact match implies a base match.
func (q *Queries) LookupTM(ctx context.Context, arg LookupTMParams) (TranslationMemory, error) {
	row := q.db.QueryRow(ctx, lookupTM,
		arg.TmID,
		arg.SourceLanguage,
		arg.SourceText,
		arg.TargetLanguage,
	)
	var i TranslationMemory
	err := row.Scan(
		&i.ID,
		&i.SourceLanguage,
		&i.TargetLanguage,
		&i.SourceText,
		&i.TargetText,
		&i.CreatedAt,
		&i.TmID,
		&i.SourceHash,
		&i.TargetHash,
		&i.UpdatedAt,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.TuID,
		&i.UsageCount,
		&i.SourceRichText,
		&i.TargetRichText,
		&i.PrevSourceHash,
		&i.NextSourceHash,
	)
	return i, err
}

