const propagateTranslation = `-- name: PropagateTranslation :many
UPDATE translations
SET step_edited      = step_edited OR active_text IS DISTINCT FROM $1,
    qe_note          = CASE WHEN active_text IS DISTINCT FROM $1 THEN NULL ELSE qe_note END,
    active_text      = $1,
    active_rich_text = $2,
    status           = 'approved',
    updated_at       = now()
WHERE locked = false
  AND NOT translation_held_by_other(translations.id, $3::bigint)
  AND id IN (
    SELECT t.id FROM translations t
    JOIN segments s ON s.id = t.segment_id
    WHERE s.file_id = $4
      AND s.source_text = $5
      AND t.target_language = $6
      AND t.id != $7
      AND NOT t.locked
    ORDER BY t.id
    FOR UPDATE OF t
)
RETURNING id, segment_id, target_language, status, predict_outcome, active_text, created_at, updated_at, editing_time_ms, edit_distance, edited_by, locked, active_rich_text, origin, tm_match_percent, in_flight_phase, qe_note, confirmed_via, step_edited
`

type PropagateTranslationParams struct {
	HumanText      *string `json:"human_text"`
	HumanRichText  *string `json:"human_rich_text"`
	ActorID        *int64  `json:"actor_id"`
	FileID         int64   `json:"file_id"`
	SourceText     string  `json:"source_text"`
	TargetLanguage string  `json:"target_language"`
	ExcludeID      int64   `json:"exclude_id"`
}

// Auto-propagation: copy a confirmed translation onto every other segment in
// the same file + target language whose source matches. Locked rows are left
// alone: a lock means "don't touch". The check sits on the outer WHERE so a
// row locked while the statement waits is re-checked and skipped.
//
// The plain and rich-text forms move together, or the siblings of a tagged
// segment lose their inline tags. RETURNING the full rows lets the frontend
// patch each sibling in its cache, so a sibling activated right after starts
// from the fresh updated_at instead of a stale one that 409s on save.
//
// A sibling a user other than @actor_id holds is skipped, like a locked one.
// The siblings are locked in id order, the order a counts recount locks them.
func (q *Queries) PropagateTranslation(ctx context.Context, arg PropagateTranslationParams) ([]Translation, error) {
	rows, err := q.db.Query(ctx, propagateTranslation,
		arg.HumanText,
		arg.HumanRichText,
		arg.ActorID,
		arg.FileID,
		arg.SourceText,
		arg.TargetLanguage,
		arg.ExcludeID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Translation{}
	for rows.Next() {
		var i Translation
		if err := rows.Scan(
			&i.ID,
			&i.SegmentID,
			&i.TargetLanguage,
			&i.Status,
			&i.PredictOutcome,
			&i.ActiveText,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.EditingTimeMs,
			&i.EditDistance,
			&i.EditedBy,
			&i.Locked,
			&i.ActiveRichText,
			&i.Origin,
			&i.TmMatchPercent,
			&i.InFlightPhase,
			&i.QeNote,
			&i.ConfirmedVia,
			&i.StepEdited,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

