const reevaluateProjectAutoComplete = `-- name: ReevaluateProjectAutoComplete :many
WITH counts AS (
  SELECT count(*) AS total,
         count(*) FILTER (WHERE j.status = 'completed') AS done
  FROM jobs j
  JOIN files f ON f.id = j.file_id
  WHERE f.project_id = $1
)
UPDATE projects p
SET status = CASE WHEN c.total > 0 AND c.done = c.total
                  THEN 'completed'::project_status
                  ELSE 'in_progress'::project_status END,
    updated_at = now()
FROM counts c, settings_profiles sp
WHERE p.id = $1 AND p.tenant_id = $2 AND p.deleted_at IS NULL
  AND sp.id = p.settings_profile_id AND sp.auto_complete
  AND p.status <> 'draft'
  AND ((c.total > 0 AND c.done = c.total
        AND p.status <> 'completed' AND p.status <> 'on_hold')
    OR ((c.total = 0 OR c.done < c.total) AND p.status = 'completed'))
RETURNING p.status
`

type ReevaluateProjectAutoCompleteParams struct {
	ProjectID int64 `json:"project_id"`
	TenantID  int64 `json:"tenant_id"`
}

// Auto-complete rule. Returns the new status, or no row
// when nothing should change — the common case, hence :many rather than :one
// (which would report "no change" as pgx.ErrNoRows).
//
// The `done < total` branch reopens a completed project that has unfinished
// work again: pipeline re-runs un-complete jobs and API uploads add new ones,
// neither of which re-evaluates.
//
// TODO(soft-delete): add `AND j.deleted_at IS NULL` once jobs carry a
// tombstone. File soft-delete must propagate to jobs.
func (q *Queries) ReevaluateProjectAutoComplete(ctx context.Context, arg ReevaluateProjectAutoCompleteParams) ([]ProjectStatus, error) {
	rows, err := q.db.Query(ctx, reevaluateProjectAutoComplete, arg.ProjectID, arg.TenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProjectStatus{}
	for rows.Next() {
		var status ProjectStatus
		if err := rows.Scan(&status); err != nil {
			return nil, err
		}
		items = append(items, status)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const refreshJobStepAssignmentDeadlines = `-- name: RefreshJobStepAssignmentDeadlines :exec
UPDATE job_step_assignments jsa
SET deadline = resolved.deadline
FROM (
    SELECT a.id,
           CASE WHEN ws.step_type IN ('ai', 'pretranslate') THEN NULL ELSE COALESCE(
               (SELECT wsa.deadline
                  FROM workflow_step_assignments wsa
                 WHERE wsa.workflow_step_id = ws.id
                   AND wsa.target_language = j.target_language),
               ws.deadline,
               p.deadline) END AS deadline
      FROM job_step_assignments a
      JOIN jobs j ON j.id = a.job_id
      JOIN files f ON f.id = j.file_id
      JOIN projects p ON p.id = f.project_id
      JOIN workflow_steps ws ON ws.id = a.workflow_step_id
     WHERE a.workflow_step_id = $1
       AND a.status IN ('pending', 'in_progress')
       AND p.tenant_id = $2 AND p.deleted_at IS NULL
) resolved
WHERE jsa.id = resolved.id
  AND jsa.deadline IS DISTINCT FROM resolved.deadline
`

type RefreshJobStepAssignmentDeadlinesParams struct {
	WorkflowStepID int64 `json:"workflow_step_id"`
	TenantID       int64 `json:"tenant_id"`
}

// Push a step's blueprint deadline onto the jobs already sitting on it,
// resolved per the job's target language. The twin of
// ReassignInFlightStepAssignments, and scoped the same way: structurally
// through job -> file -> project rather than trusting the step id, so an edit
// can never reach another tenant's assignments.
//
// Completed assignments are history and keep what they had. ReplaceWorkflowSteps
// runs this only for a step whose deadline inputs changed; when it does, a
// deadline a PM set on one job by hand is overwritten — same as a changed
// default assignee overwrites one, so the two edits behave alike.
//
// The project's own deadline is the last resort, so a step nobody scheduled
// still gives its tasks the date the whole project is due. An ai step is
// excluded outright: it completes itself, and a DB constraint keeps its
// blueprint row deadline-free, so the fallback must not sneak one in.
//
// The override is a scalar subquery, not a join: a step carrying rows for
// other languages must still fall back to its own deadline for this job's
// language, which a join on workflow_step_assignments would filter away
// instead. A row that carries no deadline needs no guard here — COALESCE
// treats the NULL it returns exactly like the missing row.
