const saveTranslationDraft = `-- name: SaveTranslationDraft :one
UPDATE translations
SET step_edited = step_edited OR active_text IS DISTINCT FROM $1,
    qe_note     = CASE WHEN active_text IS DISTINCT FROM $1 THEN NULL ELSE qe_note END,
    active_text = $1, active_rich_text = $2,
    status = 'needs_review',
    -- A draft is never locked: a locked segment is always approved. Only
    -- find and replace with "Include locked" (owner/admin) drafts one.
    locked = false,
    editing_time_ms = editing_time_ms + $3,
    edited_by = $4,
    updated_at = now()
WHERE id = $5
  AND ($6::timestamptz IS NULL
       OR updated_at = $6::timestamptz)
  AND NOT translation_held_by_other(translations.id, $4)
RETURNING id, segment_id, target_language, status, predict_outcome, active_text, created_at, updated_at, editing_time_ms, edit_distance, edited_by, locked, active_rich_text, origin, tm_match_percent, in_flight_phase, qe_note, confirmed_via, step_edited
`

type SaveTranslationDraftParams struct {
	HumanText          *string            `json:"human_text"`
	HumanRichText      *string            `json:"human_rich_text"`
	DeltaEditingTimeMs int64              `json:"delta_editing_time_ms"`
	EditedBy           *int64             `json:"edited_by"`
	ID                 int64              `json:"id"`
	ExpectedUpdatedAt  pgtype.Timestamptz `json:"expected_updated_at"`
}

// Auto-save draft: persists the user's typing without promoting to 'approved'.
// Always sets status='needs_review' regardless of the prior status — a draft
// save means "the user typed and we're persisting the edit," which by definition
// is no longer in any prior state. Drops 'approved' / 'auto_approved' back to
// 'needs_review' so the row no longer counts as confirmed and the completion
// dialog warns the PM.
//
// Optimistic locking: same shape as UpdateTranslationHuman —
// pass @expected_updated_at to enforce version check, NULL to skip it.
//
// A draft writes no TEXT row to
// translation_history — only confirms do, and that is what keeps the
// edit-distance baseline honest. The handler does emit one text-less
// `unconfirmed` row when this save takes an approval away.
//
// Hold guard as in UpdateTranslationHuman: a row another user holds matches
// nothing, whatever the lock or version.
func (q *Queries) SaveTranslationDraft(ctx context.Context, arg SaveTranslationDraftParams) (Translation, error) {
	row := q.db.QueryRow(ctx, saveTranslationDraft,
		arg.HumanText,
		arg.HumanRichText,
		arg.DeltaEditingTimeMs,
		arg.EditedBy,
		arg.ID,
		arg.ExpectedUpdatedAt,
	)
	var i Translation
	err := row.Scan(
		&i.ID,
		&i.SegmentID,
		&i.TargetLanguage,
		&i.Status,
		&i.PredictOutcome,
		&i.ActiveText,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.EditingTimeMs,
		&i.EditDistance,
		&i.EditedBy,
		&i.Locked,
		&i.ActiveRichText,
		&i.Origin,
		&i.TmMatchPercent,
		&i.InFlightPhase,
		&i.QeNote,
		&i.ConfirmedVia,
		&i.StepEdited,
	)
	return i, err
}

const searchTMEntries = `-- name: SearchTMEntries :many
SELECT id, tm_id, source_language, target_language, source_text, target_text,
       source_rich_text, target_rich_text, created_at,
       GREATEST(similarity(source_text, $1::text), similarity(target_text, $1::text)) AS score
FROM translation_memory
WHERE tm_id = $2
  AND ($3::text = '' OR source_language = $3)
  AND ($4::text = '' OR target_language = $4)
  AND (source_text ILIKE '%' || $1 || '%' OR target_text ILIKE '%' || $1 || '%')
ORDER BY score DESC
LIMIT $5
`

type SearchTMEntriesParams struct {
	Query          string `json:"query"`
	TmID           int64  `json:"tm_id"`
	SourceLanguage string `json:"source_language"`
	TargetLanguage string `json:"target_language"`
	EntryLimit     int32  `json:"entry_limit"`
}

type SearchTMEntriesRow struct {
	ID             int64              `json:"id"`
	TmID           int64              `json:"tm_id"`
	SourceLanguage string             `json:"source_language"`
	TargetLanguage string             `json:"target_language"`
	SourceText     string             `json:"source_text"`
	TargetText     string             `json:"target_text"`
	SourceRichText *string            `json:"source_rich_text"`
	TargetRichText *string            `json:"target_rich_text"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
	Score          interface{}        `json:"score"`
}

func (q *Queries) SearchTMEntries(ctx context.Context, arg SearchTMEntriesParams) ([]SearchTMEntriesRow, error) {
	rows, err := q.db.Query(ctx, searchTMEntries,
		arg.Query,
		arg.TmID,
		arg.SourceLanguage,
		arg.TargetLanguage,
		arg.EntryLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchTMEntriesRow{}
	for rows.Next() {
		var i SearchTMEntriesRow
		if err := rows.Scan(
			&i.ID,
			&i.TmID,
			&i.SourceLanguage,
			&i.TargetLanguage,
			&i.SourceText,
			&i.TargetText,
			&i.SourceRichText,
			&i.TargetRichText,
			&i.CreatedAt,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchTMEntriesCursor = `-- name: SearchTMEntriesCursor :many
SELECT id, tm_id, source_language, target_language, source_text, target_text,
       source_rich_text, target_rich_text, created_at, updated_at, updated_by,
       GREATEST(similarity(source_text, $1::text), similarity(target_text, $1::text)) AS score
FROM translation_memory
WHERE tm_id = $2
  AND ($3::text = '' OR source_language = $3)
  AND ($4::text = '' OR target_language = $4)
  AND (($5::bool AND CASE WHEN $6::bool THEN source_text ~ $7::text ELSE source_text ~* $7::text END)
    OR ($8::bool AND CASE WHEN $6::bool THEN target_text ~ $7::text ELSE target_text ~* $7::text END))
  AND id > $9
ORDER BY id
LIMIT $10
`

