const setQAResultIgnored = `-- name: SetQAResultIgnored :one
UPDATE qa_results qr
SET ignored       = $1::boolean,
    ignored_by    = CASE WHEN $1::boolean THEN $2::bigint ELSE NULL END,
    ignored_at    = CASE WHEN $1::boolean THEN now() ELSE NULL END
FROM translations t
JOIN segments s ON s.id = t.segment_id
JOIN files f ON f.id = s.file_id
JOIN projects p ON p.id = f.project_id
WHERE qr.translation_id = t.id
  AND qr.translation_id = $3
  AND qr.check_type = $4
  AND p.tenant_id = $5 AND p.deleted_at IS NULL
RETURNING qr.id, qr.translation_id, qr.check_type, qr.severity, qr.message, qr.created_at, qr.ignored, qr.ignored_by, qr.ignored_at
`

