const settingsConcordanceSearch = `-- name: SettingsConcordanceSearch :many

SELECT tm.id, tm.source_language, tm.target_language, tm.source_text, tm.target_text,
       tm.source_rich_text, tm.target_rich_text,
       tc.name AS tm_name
FROM translation_memory tm
JOIN tm_collections tc ON tc.id = tm.tm_id AND tc.deleted_at IS NULL
JOIN settings_tm_assignments sta ON sta.tm_id = tm.tm_id
WHERE sta.settings_profile_id = tm_scope_profile_id($1)
  -- TM assignments carry no languages; filter concordance hits
  -- by the TM entry's own language pair (base-language fallback), scoped to the
  -- TMs assigned to this profile.
  AND (tm.source_language = $2
       OR SPLIT_PART(tm.source_language, '-', 1) = SPLIT_PART($2, '-', 1))
  AND (tm.target_language = $3
       OR SPLIT_PART(tm.target_language, '-', 1) = SPLIT_PART($3, '-', 1))
  AND (tm.source_text ILIKE '%' || $4 || '%' OR tm.target_text ILIKE '%' || $4 || '%')
ORDER BY CASE WHEN tm.source_text ILIKE $4 THEN 0 ELSE 1 END, tm.source_text
LIMIT $5
`

type SettingsConcordanceSearchParams struct {
	SettingsProfileID int64   `json:"settings_profile_id"`
	SourceLanguage    string  `json:"source_language"`
	TargetLanguage    string  `json:"target_language"`
	Query             *string `json:"query"`
	EntryLimit        int32   `json:"entry_limit"`
}

type SettingsConcordanceSearchRow struct {
	ID             int64   `json:"id"`
	SourceLanguage string  `json:"source_language"`
	TargetLanguage string  `json:"target_language"`
	SourceText     string  `json:"source_text"`
	TargetText     string  `json:"target_text"`
	SourceRichText *string `json:"source_rich_text"`
	TargetRichText *string `json:"target_rich_text"`
	TmName         string  `json:"tm_name"`
}

// ============================================================
// Concordance Search
// Substring match across TMs assigned to a settings profile for a language pair.
// ============================================================
// source_rich_text / target_rich_text are returned alongside plain text so
// the Concordance modal can render inline tags as atomic chips.
// Frontend prefers rich_text when non-null, falls back to plain otherwise.
func (q *Queries) SettingsConcordanceSearch(ctx context.Context, arg SettingsConcordanceSearchParams) ([]SettingsConcordanceSearchRow, error) {
	rows, err := q.db.Query(ctx, settingsConcordanceSearch,
		arg.SettingsProfileID,
		arg.SourceLanguage,
		arg.TargetLanguage,
		arg.Query,
		arg.EntryLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SettingsConcordanceSearchRow{}
	for rows.Next() {
		var i SettingsConcordanceSearchRow
		if err := rows.Scan(
			&i.ID,
			&i.SourceLanguage,
			&i.TargetLanguage,
			&i.SourceText,
			&i.TargetText,
			&i.SourceRichText,
			&i.TargetRichText,
			&i.TmName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const settingsTermConcordanceSearch = `-- name: SettingsTermConcordanceSearch :many
SELECT tgt.id, src.text AS source_term, tgt.text AS target_term, tgt.status, tgt.notes,
       tb.name AS term_base_name
FROM term src
JOIN term_concept c ON c.id = src.concept_id AND c.deleted_at IS NULL AND src.deleted_at IS NULL
JOIN term tgt ON tgt.concept_id = c.id
  AND tgt.deleted_at IS NULL
JOIN term_bases tb ON tb.id = c.term_base_id AND tb.deleted_at IS NULL
WHERE EXISTS (
  SELECT 1 FROM settings_terminology_assignments sta
  WHERE sta.term_base_id = tb.id
    AND sta.settings_profile_id = $1
    AND (sta.source_language = $2
         OR SPLIT_PART(sta.source_language, '-', 1) = SPLIT_PART($2, '-', 1))
    AND (sta.target_language = $3
         OR SPLIT_PART(sta.target_language, '-', 1) = SPLIT_PART($3, '-', 1))
)
  AND (src.language = $2
       OR SPLIT_PART(src.language, '-', 1) = SPLIT_PART($2, '-', 1))
  AND (tgt.language = $3
       OR SPLIT_PART(tgt.language, '-', 1) = SPLIT_PART($3, '-', 1))
  AND (src.text ILIKE '%' || $4 || '%' OR tgt.text ILIKE '%' || $4 || '%')
ORDER BY CASE WHEN src.text ILIKE $4 THEN 0 ELSE 1 END, src.text
LIMIT $5
`

type SettingsTermConcordanceSearchParams struct {
	SettingsProfileID int64   `json:"settings_profile_id"`
	SourceLanguage    string  `json:"source_language"`
	TargetLanguage    string  `json:"target_language"`
	Query             *string `json:"query"`
	EntryLimit        int32   `json:"entry_limit"`
}

type SettingsTermConcordanceSearchRow struct {
	ID           int64  `json:"id"`
	SourceTerm   string `json:"source_term"`
	TargetTerm   string `json:"target_term"`
	Status       string `json:"status"`
	Notes        string `json:"notes"`
	TermBaseName string `json:"term_base_name"`
}

// Concordance search across term bases assigned to a settings profile.
// Projects the concept model (source term × target term of the same concept).
// EXISTS (semi-join): a base with multiple matching assignment rows must not
// multiply concordance hits (see LookupSettingsTerms). No priority needed here.
func (q *Queries) SettingsTermConcordanceSearch(ctx context.Context, arg SettingsTermConcordanceSearchParams) ([]SettingsTermConcordanceSearchRow, error) {
	rows, err := q.db.Query(ctx, settingsTermConcordanceSearch,
		arg.SettingsProfileID,
		arg.SourceLanguage,
		arg.TargetLanguage,
		arg.Query,
		arg.EntryLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SettingsTermConcordanceSearchRow{}
	for rows.Next() {
		var i SettingsTermConcordanceSearchRow
		if err := rows.Scan(
			&i.ID,
			&i.SourceTerm,
			&i.TargetTerm,
			&i.Status,
			&i.Notes,
			&i.TermBaseName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

