const unlockJobTranslations = `-- name: UnlockJobTranslations :many
UPDATE translations
SET locked = false, updated_at = now()
WHERE segment_id IN (SELECT id FROM segments WHERE file_id = $1)
  AND target_language = $2
  AND id = ANY($3::bigint[])
  AND locked
RETURNING id
`

type UnlockJobTranslationsParams struct {
	FileID         int64   `json:"file_id"`
	TargetLanguage string  `json:"target_language"`
	Ids            []int64 `json:"ids"`
}

// Unlocks the rows of @ids in the job's file + target language (tenant scope
// as in ListJobTranslationsByIDs). Rows already unlocked are left alone and
// not returned. The status stays.
func (q *Queries) UnlockJobTranslations(ctx context.Context, arg UnlockJobTranslationsParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, unlockJobTranslations, arg.FileID, arg.TargetLanguage, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

