const updateTranslationFromReimport = `-- name: UpdateTranslationFromReimport :execrows
UPDATE translations
SET step_edited      = step_edited OR active_text IS DISTINCT FROM $1,
    qe_note          = CASE WHEN active_text IS DISTINCT FROM $1 THEN NULL ELSE qe_note END,
    active_text      = $1,
    active_rich_text = $2,
    status           = 'needs_review',
    edited_by        = $3,
    updated_at       = now()
WHERE id = $4
  AND NOT translation_held_by_other(translations.id, $3)
`

type UpdateTranslationFromReimportParams struct {
	HumanText     *string `json:"human_text"`
	HumanRichText *string `json:"human_rich_text"`
	EditedBy      *int64  `json:"edited_by"`
	ID            int64   `json:"id"`
}

// XLIFF re-import: stamps a translation with the incoming target. Treats the
// incoming text as a manual edit from outside OpenLoc, so it writes the
// active_* columns but sets status to 'needs_review' rather than
// 'approved' — a re-import is a fresh edit that PMs should explicitly
// re-confirm. The `file_import` provenance lives in
// translation_history (the reimport handler emits a `file_import`
// automation event).
// edited_by records the admin who triggered the re-import (audit trail —
// the actual text came from outside OpenLoc, but the operation was
// performed by a known user).
// A row a user other than @edited_by holds is not written: zero rows.
func (q *Queries) UpdateTranslationFromReimport(ctx context.Context, arg UpdateTranslationFromReimportParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateTranslationFromReimport,
		arg.HumanText,
		arg.HumanRichText,
		arg.EditedBy,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateTranslationHuman = `-- name: UpdateTranslationHuman :one
UPDATE translations
SET step_edited = step_edited OR active_text IS DISTINCT FROM $1,
    qe_note     = CASE WHEN active_text IS DISTINCT FROM $1 THEN NULL ELSE qe_note END,
    active_text = $1, active_rich_text = $2,
    status = 'approved',
    confirmed_via = COALESCE($3::text, 'user'),
    editing_time_ms = editing_time_ms + $4,
    edit_distance = $5,
    edited_by = $6,
    updated_at = now()
WHERE id = $7
  AND ($8::timestamptz IS NULL
       OR updated_at = $8::timestamptz)
  AND NOT translation_held_by_other(translations.id, COALESCE($9::bigint, $6))
RETURNING id, segment_id, target_language, status, predict_outcome, active_text, created_at, updated_at, editing_time_ms, edit_distance, edited_by, locked, active_rich_text, origin, tm_match_percent, in_flight_phase, qe_note, confirmed_via, step_edited
`

type UpdateTranslationHumanParams struct {
	HumanText          *string            `json:"human_text"`
	HumanRichText      *string            `json:"human_rich_text"`
	ConfirmedVia       *string            `json:"confirmed_via"`
	DeltaEditingTimeMs int64              `json:"delta_editing_time_ms"`
	EditDistance       int32              `json:"edit_distance"`
	EditedBy           *int64             `json:"edited_by"`
	ID                 int64              `json:"id"`
	ExpectedUpdatedAt  pgtype.Timestamptz `json:"expected_updated_at"`
	ActorID            *int64             `json:"actor_id"`
}

// Optimistic locking: if @expected_updated_at is non-null, the row only
// updates when the current updated_at matches. A mismatch returns zero rows,
// which sqlc surfaces as pgx.ErrNoRows — the caller maps that to 409 Conflict.
// Passing NULL preserves the legacy behavior (no version check) for callers
// that don't track updated_at (background workers, tests).
//
// The translation_history `human` event is the audit; the sticky `origin`
// column is left untouched (a human action does not reset automation
// lineage).
//
// confirmed_via: NULL means a person confirmed ('user'); the assistant's
// confirm passes 'assistant', which keeps the row out of TM write-back.
//
// A row another user holds (a live translation_holds row) is not written:
// zero rows, like a version mismatch. The writer is @actor_id, else
// @edited_by: the TM exact-match confirm records no editor but passes the
// holds of the user who ran it. IS DISTINCT FROM, so a write with neither is
